class Solution {
public:
    std::vector<int> colorTheArray(int n, std::vector<std::vector<int>>& queries) {
        std::vector<int> nums(n, 0);
        int same_adj = 0;
        std::vector<int> ans;
        for (const auto& q : queries) {
            int idx = q[0], color = q[1];
            if (nums[idx] != 0) {
                if (idx > 0 && nums[idx] == nums[idx - 1]) same_adj--;
                if (idx < n - 1 && nums[idx] == nums[idx + 1]) same_adj--;
            }
            nums[idx] = color;
            if (nums[idx] != 0) {
                if (idx > 0 && nums[idx] == nums[idx - 1]) same_adj++;
                if (idx < n - 1 && nums[idx] == nums[idx + 1]) same_adj++;
            }
            ans.push_back(same_adj);
        }
        return ans;
    }
};

