var colorTheArray = function(n, queries) {
    const nums = new Array(n).fill(0);
    let sameAdj = 0;
    const ans = [];
    for (const [idx, color] of queries) {
        if (nums[idx] !== 0) {
            if (idx > 0 && nums[idx] === nums[idx - 1]) sameAdj--;
            if (idx < n - 1 && nums[idx] === nums[idx + 1]) sameAdj--;
        }
        nums[idx] = color;
        if (nums[idx] !== 0) {
            if (idx > 0 && nums[idx] === nums[idx - 1]) sameAdj++;
            if (idx < n - 1 && nums[idx] === nums[idx + 1]) sameAdj++;
        }
        ans.push(sameAdj);
    }
    return ans;
};
